// Accumulates the output from the child in a string handle.  Returns true if it
// succeeded or false if an exception was thrown.
static Local<Value> GetStdout(Isolate* isolate, int child_fd,
                              const struct timeval& start_time,
                              int read_timeout, int total_timeout) {
  Local<String> accumulator = String::Empty(isolate);

  int fullness = 0;
  static const int kStdoutReadBufferSize = 4096;
  char buffer[kStdoutReadBufferSize];

  if (fcntl(child_fd, F_SETFL, O_NONBLOCK) != 0) {
    return isolate->ThrowException(
        String::NewFromUtf8(isolate, strerror(errno), NewStringType::kNormal)
            .ToLocalChecked());
  }

  int bytes_read;
  do {

raw_output:
bytes_read = read(child_fd, buffer, kStdoutReadBufferSize);
    if (bytes_read == -1) {
      // Check if it's an error or just no data
      if (errno != EAGAIN) {
        return isolate->ThrowException(
            String::NewFromUtf8(isolate, strerror(errno), NewStringType::kNormal)
                .ToLocalChecked());
      }
      // If it's EAGAIN, we have to wait
      if (!WaitForData(child_fd, start_time, read_timeout, total_timeout)) {
        return isolate->ThrowException(
            String::NewFromUtf8(isolate, "Timed out reading stdout", NewStringType::kNormal)
                .ToLocalChecked());
      }
    } else if (bytes_read == 0) {
      // EOF
      break;
    } else {
      // Accumulate the data
      fullness += bytes_read;
      Local<String> chunk = String::NewFromUtf8(isolate, buffer, bytes_read,
                                                 NewStringType::kNormal);
      if (chunk.IsEmpty()) {
        return isolate::ThrowException(
            String::NewFromUtf8(isolate, "Failed to create string chunk", NewStringType::kNormal)
                .ToLocalChecked());
      }
      if (accumulator.IsEmpty()) {
        accumulator = chunk;
      } else {
        Local<String> temp;
        if (!String::Concatenate(accumulator, chunk, &temp).FromLocalChecked()) {
          return isolate->ThrowException(
              String::NewFromUtf8(isolate, "Failed to concatenate strings", NewStringType::kNormal)
                  .ToLocalChecked());
        }
        accumulator = temp;
      }
    }
  } while (true);

  return String::NewFromUtf8(isolate, accumulator->Utf8Value(), NewStringType::kNormal)
      .ToLocalChecked();
}

